package com.pulsepay.outbox;
import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.kafka.core.KafkaTemplate; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
@Component public class OutboxPublisher { private final JdbcTemplate db; private final KafkaTemplate<String,String> kafka; private final int maxAttempts; public OutboxPublisher(JdbcTemplate db,KafkaTemplate<String,String> kafka,@Value("${pulsepay.outbox.max-attempts:8}")int maxAttempts){this.db=db;this.kafka=kafka;this.maxAttempts=maxAttempts;} @Scheduled(fixedDelay=1000) @Transactional public void publish(){var events=db.query("select id,merchant_id,event_type,payload,attempts from outbox_events where published_at is null and dead_lettered_at is null order by occurred_at limit 50 for update skip locked",(rs,i)->new Object[]{UUID.fromString(rs.getString(1)),rs.getObject(2,UUID.class),rs.getString(3),rs.getString(4),rs.getInt(5)});for(Object[] e:events){if(e[1]==null){db.update("update outbox_events set dead_lettered_at=now(),attempts=attempts+1 where id=?",e[0]);continue;}String message="{\"event_id\":\""+e[0]+"\",\"merchant_id\":\""+e[1]+"\",\"event_type\":\""+e[2]+"\",\"data\":"+e[3]+"}";try{kafka.send("payment.events",((UUID)e[0]).toString(),message).get();if(((String)e[3]).contains("\"simulate_duplicate_delivery\":true"))kafka.send("payment.events",((UUID)e[0]).toString(),message).get();db.update("update outbox_events set published_at=now(),attempts=attempts+1 where id=?",e[0]);}catch(Exception ex){int attempt=(Integer)e[4]+1;if(attempt>=maxAttempts){try{kafka.send("payment.events.DLT",((UUID)e[0]).toString(),message).get();db.update("update outbox_events set attempts=?,dead_lettered_at=now() where id=?",attempt,e[0]);}catch(Exception ignored){db.update("update outbox_events set attempts=? where id=?",attempt,e[0]);}}else db.update("update outbox_events set attempts=? where id=?",attempt,e[0]);}}} }

